from collections import deque
def enclosed_bg(I, bg):
    R,C=len(I),len(I[0])
    seen=[[False]*C for _ in range(R)]
    q=deque()
    for r in range(R):
        for c in (0,C-1):
            if I[r][c]==bg and not seen[r][c]: seen[r][c]=True;q.append((r,c))
    for c in range(C):
        for r in (0,R-1):
            if I[r][c]==bg and not seen[r][c]: seen[r][c]=True;q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and I[nr][nc]==bg and not seen[nr][nc]:
                seen[nr][nc]=True;q.append((nr,nc))
    return {(r,c) for r in range(R) for c in range(C) if I[r][c]==bg and not seen[r][c]}
