def solve(I):
    I=np.array(I); shape=I[0,0]
    bg=[v for v in np.unique(I) if v!=shape]
    bg=max(bg,key=lambda v:(I==v).sum()) if bg else None
    if bg is None: return I.tolist()
    ys,xs=np.where(I==shape)
    r0,r1,c0,c1=ys.min(),ys.max(),xs.min(),xs.max()
    O=I.copy()
    for r in range(r0,r1+1):
        for c in (c0,c1):
            if O[r,c]==bg: O[r,c]=2
    for c in range(c0,c1+1):
        for r in (r0,r1):
            if O[r,c]==bg: O[r,c]=2
    return O.tolist()
